BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path = public, extensions;
SELECT no_plan();
SELECT ok(NOT has_function_privilege('authenticated', 'public.finalize_priced_snapshot(uuid,jsonb,jsonb,text)', 'EXECUTE'), 'clients cannot finalize valuations');
SELECT ok(NOT has_function_privilege('anon', 'public.finalize_priced_snapshot(uuid,jsonb,jsonb,text)', 'EXECUTE'), 'anonymous cannot finalize valuations');
SELECT ok(has_function_privilege('service_role', 'public.finalize_priced_snapshot(uuid,jsonb,jsonb,text)', 'EXECUTE'), 'server can finalize valuations');
SELECT is_empty($$SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename IN ('stash_snapshots','stash_tabs','stash_items','snapshot_value_history','group_wealth_history','group_wealth_history_contributions') AND (has_table_privilege('authenticated', 'public.'||tablename,'INSERT') OR has_table_privilege('authenticated','public.'||tablename,'UPDATE') OR has_table_privilege('authenticated','public.'||tablename,'DELETE'))$$, 'capture and valuation tables have no broad client writes');
INSERT INTO auth.users(id,email) VALUES ('1c000000-0000-0000-0000-000000000001','pricing-a@example.invalid'),('1c000000-0000-0000-0000-000000000002','pricing-b@example.invalid');
INSERT INTO public.users(id,poe_account_name) VALUES ('1c000000-0000-0000-0000-000000000001','PricingA#0001'),('1c000000-0000-0000-0000-000000000002','PricingB#0002');
INSERT INTO public.groups(id,name,invite_code,created_by,game,league) VALUES ('2c000000-0000-0000-0000-000000000001','Pricing A','price001','1c000000-0000-0000-0000-000000000001','poe1','Covens'),('2c000000-0000-0000-0000-000000000002','Pricing B','price002','1c000000-0000-0000-0000-000000000002','poe1','Covens');
INSERT INTO public.group_members(group_id,user_id,role) VALUES ('2c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000001','admin'),('2c000000-0000-0000-0000-000000000002','1c000000-0000-0000-0000-000000000002','admin');
INSERT INTO public.stash_snapshots(id,user_id,group_id,status) VALUES ('4c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000001','2c000000-0000-0000-0000-000000000001','in_progress');
INSERT INTO public.stash_tabs(id,snapshot_id,user_id,group_id,poe_tab_id,name,tab_type,tab_index) VALUES ('5c000000-0000-0000-0000-000000000001','4c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000001','2c000000-0000-0000-0000-000000000001','p1','Pricing','NormalStash',0);
INSERT INTO public.stash_items(id,tab_id,user_id,group_id,poe_item_id,name,type_line,raw_data) VALUES ('6c000000-0000-0000-0000-000000000001','5c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000001','2c000000-0000-0000-0000-000000000001','i1','Breach Thread','Breach Thread','{}'),('6c000000-0000-0000-0000-000000000002','5c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000001','2c000000-0000-0000-0000-000000000001','i2','Unknown','Unknown','{}');
SELECT set_config('request.jwt.claims','{"sub":"1c000000-0000-0000-0000-000000000001","role":"service_role"}',true);
SELECT throws_ok($$SELECT public.finalize_priced_snapshot('4c000000-0000-0000-0000-000000000001','[]','{"status":"complete","version":1,"source":"poe.ninja"}')$$, 'P0001','Pricing must cover exactly the snapshot items','missing item rows roll back');
SELECT is((SELECT status::text FROM public.stash_snapshots WHERE id='4c000000-0000-0000-0000-000000000001'),'in_progress','failed finalization does not publish completion');
SELECT throws_ok($$SELECT public.finalize_priced_snapshot('4c000000-0000-0000-0000-000000000001','[]','{"version":1,"source":"poe.ninja"}')$$,'P0001','Invalid pricing summary','missing feed status is rejected');
SELECT lives_ok($$SELECT public.finalize_priced_snapshot('4c000000-0000-0000-0000-000000000001','[{"id":"6c000000-0000-0000-0000-000000000001","price_chaos":20,"price_divine":null},{"id":"6c000000-0000-0000-0000-000000000002","price_chaos":null,"price_divine":null}]','{"status":"complete","version":1,"source":"poe.ninja","divine_price":null,"priced_item_count":999}')$$,'server finalizes exact rows');
SELECT is((SELECT price_chaos FROM public.stash_items WHERE id='6c000000-0000-0000-0000-000000000002'),NULL::numeric,'unknown remains null');
SELECT is((SELECT pricing_summary->>'priced_item_count' FROM public.stash_snapshots WHERE id='4c000000-0000-0000-0000-000000000001'),'1','counts computed by database');
SELECT is((SELECT included_chaos_total FROM public.snapshot_value_history WHERE snapshot_id='4c000000-0000-0000-0000-000000000001'),20::numeric,'stored subtotal matches history');
SELECT is((SELECT total_wealth_chaos FROM public.group_wealth_history WHERE triggered_by_snapshot_id='4c000000-0000-0000-0000-000000000001'),20::numeric,'group point uses stored prices');
SELECT set_config('request.jwt.claims','{"sub":"1c000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$UPDATE public.stash_items SET price_chaos=999 WHERE id='6c000000-0000-0000-0000-000000000001'$$,'42501','permission denied for table stash_items','owner cannot forge prices');
SELECT throws_ok($$INSERT INTO public.group_wealth_history(group_id,triggered_by_user_id,total_wealth_chaos,member_count,pricing_summary) VALUES ('2c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000001',999,1,'{"status":"complete","version":1}')$$,'42501','permission denied for table group_wealth_history','owner cannot forge trusted group history');
SELECT throws_ok($$SELECT public.bulk_update_snapshot_item_prices('4c000000-0000-0000-0000-000000000001','[{"id":"6c000000-0000-0000-0000-000000000001","price_chaos":999}]')$$,'P0001','Snapshot prices are server-owned','legacy RPC cannot forge prices');
SELECT lives_ok($$SELECT public.set_snapshot_item_excluded('6c000000-0000-0000-0000-000000000001',true)$$,'owner exclusion still works through definer chain');
SELECT is((SELECT included_chaos_total FROM public.snapshot_value_history WHERE snapshot_id='4c000000-0000-0000-0000-000000000001'),0::numeric,'exclusion updates trusted subtotal');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"1c000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT is_empty($$SELECT id FROM public.stash_items WHERE group_id='2c000000-0000-0000-0000-000000000001'$$,'unrelated account cannot read pricing rows');
SELECT throws_ok($$SELECT public.set_snapshot_item_excluded('6c000000-0000-0000-0000-000000000001',false)$$,'P0001','Snapshot item not found for id 6c000000-0000-0000-0000-000000000001','unrelated account cannot exclude items');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"1c000000-0000-0000-0000-000000000001","role":"service_role"}',true);
INSERT INTO public.stash_snapshots(id,user_id,group_id,status) VALUES ('4c000000-0000-0000-0000-000000000002','1c000000-0000-0000-0000-000000000001','2c000000-0000-0000-0000-000000000001','in_progress');
SELECT lives_ok($$SELECT public.finalize_priced_snapshot('4c000000-0000-0000-0000-000000000002','[]','{"status":"unavailable","version":1,"source":"poe.ninja"}')$$,'unavailable capture remains completed raw data');
SELECT is((SELECT status::text FROM public.stash_snapshots WHERE id='4c000000-0000-0000-0000-000000000002'),'completed','raw capture completes during outage');
SELECT is_empty($$SELECT id FROM public.snapshot_value_history WHERE snapshot_id='4c000000-0000-0000-0000-000000000002'$$,'outage creates no zero history point');
INSERT INTO public.group_members(group_id,user_id,role) VALUES ('2c000000-0000-0000-0000-000000000001','1c000000-0000-0000-0000-000000000002','viewer');
INSERT INTO public.stash_snapshots(id,user_id,group_id,status) VALUES ('4c000000-0000-0000-0000-000000000003','1c000000-0000-0000-0000-000000000002','2c000000-0000-0000-0000-000000000001','in_progress');
SELECT lives_ok($$SELECT public.finalize_priced_snapshot('4c000000-0000-0000-0000-000000000003','[]','{"status":"complete","version":1,"source":"poe.ninja"}')$$,'another member can finalize after upstream outage');
SELECT is_empty($$SELECT id FROM public.group_wealth_history WHERE triggered_by_snapshot_id='4c000000-0000-0000-0000-000000000003'$$,'unavailable latest member cannot disappear from group valuation');
SELECT is((SELECT count(*)::integer FROM public.group_wealth_history WHERE group_id='2c000000-0000-0000-0000-000000000001'),1,'old group point remains intact');
-- Bulk finalization is independent of the REST row cap.
INSERT INTO public.stash_snapshots(id,user_id,group_id,status) VALUES ('4c000000-0000-0000-0000-000000000004','1c000000-0000-0000-0000-000000000002','2c000000-0000-0000-0000-000000000002','in_progress');
INSERT INTO public.stash_tabs(id,snapshot_id,user_id,group_id,poe_tab_id,name,tab_type,tab_index) VALUES ('5c000000-0000-0000-0000-000000000004','4c000000-0000-0000-0000-000000000004','1c000000-0000-0000-0000-000000000002','2c000000-0000-0000-0000-000000000002','p4','Large stash','NormalStash',0);
INSERT INTO public.stash_items(tab_id,user_id,group_id,poe_item_id,name,type_line,raw_data)
SELECT '5c000000-0000-0000-0000-000000000004','1c000000-0000-0000-0000-000000000002','2c000000-0000-0000-0000-000000000002','bulk-'||i,'Thread','Breach Thread','{}'::jsonb FROM generate_series(1,1001) i;
SELECT lives_ok($query$SELECT public.finalize_priced_snapshot('4c000000-0000-0000-0000-000000000004',(SELECT jsonb_agg(jsonb_build_object('id',id,'price_chaos',1,'price_divine',null)) FROM public.stash_items WHERE tab_id='5c000000-0000-0000-0000-000000000004'),'{"status":"partial","version":1,"source":"poe.ninja"}')$query$,'all 1001 item values finalize atomically');
SELECT is((SELECT included_chaos_total FROM public.snapshot_value_history WHERE snapshot_id='4c000000-0000-0000-0000-000000000004'),1001::numeric,'subtotal includes item beyond row 1000');
SELECT is((SELECT pricing_summary->>'status' FROM public.group_wealth_history WHERE triggered_by_snapshot_id='4c000000-0000-0000-0000-000000000004'),'partial','partial feed state survives durable group history');
SELECT lives_ok($query$SELECT public.refresh_group_wealth_history_for_snapshot('4c000000-0000-0000-0000-000000000002')$query$,'refreshing unavailable capture remains safe');
SELECT is_empty($query$SELECT id FROM public.group_wealth_history WHERE triggered_by_snapshot_id='4c000000-0000-0000-0000-000000000002'$query$,'unavailable capture never becomes a valued group point');
SELECT finish();
ROLLBACK;
